// Stage 8 Grammar Lab missions, in the same format as js/glab.js: one mission per unit for Units 2-4. Help (hint,
// explain, twin) is written on each question here, so js/glab.js has nothing to merge for them. blockFor(why) names the
// building block a wrong option shows (see BLOCKS in js/glab.js); typed questions name theirs with b.
// Mission ids start glab-8- and question ids g8-/u8-/p8-, so Stage 9 results never mix. Don't rename ids.

const C = (stem, right, ...wrong) => ({ stem, opts: [{ t: right }, ...wrong.map(([t, why, b]) => ({ t, why, ...(b ? { b } : {}) }))] });

